def main():
    output = ROOT / DEFAULT_OUTPUT
    manifest = json.loads((output / "split-manifest.json").read_text(encoding="utf-8"))
    contacts = json.loads((output / "review/contact-manifest.json").read_text(encoding="utf-8"))
    reviewed = sorted(set(manifest["color_training_ids"] + manifest["calibration_ids"] + manifest["regression_ids"]))
    write_json(output / "review/visual-review.json", {"reviewer": "codex_visual", "human_reviewed": False,
        "method": "actual paired raw-image contact sheets viewed with view_image before predictions",
        "reviewed_ids": reviewed, "frame_ids": [{"sample": value, "primary": metadata(value)["primary_frame_id"],
            "side": metadata(value)["side_frame_id"]} for value in reviewed],
        "source_marks_modified": False, "roi_review": "tray object shown; side equipment outside tray excluded from review thumbnail only",
        "depth_review": "raw RGB review does not establish depth validity; depth previews and runtime owned-depth diagnostics reviewed separately",
        "findings": ["blue side dark faces", "octahedron surface glints are not ridges", "square-pyramid single-face views have hidden ridges",
            "yellow cone specular stripe is not a ridge", "green/red face shadows preserve one instance", "red curved samples absent",
            "single object per capture; touching-instance validation is synthetic", "raw bule retained and canonical blue used only on read"],
        "contact_hashes": {path: hashlib.sha256((output / path).read_bytes()).hexdigest() for paths in contacts.values() for path in paths}})
    records = []
    for split, definitions in (("calibration", CAL), ("regression", REG)):
        identifiers = manifest[f"annotation_{split}_ids"]
        transforms = json.loads((output / f"review/annotation-{split}-coordinates.json").read_text(encoding="utf-8"))
        assert len(identifiers) == len(definitions) == 24
        overlays = {}
        for index, (identifier, pair) in enumerate(zip(identifiers, definitions)):
            curved = Path(identifier).parent.name == "cone"
            record = {"sample": identifier, "partition": split, "reviewer": "codex_visual_manual_points",
                "human_ground_truth": False, "raw_color": metadata(identifier)["color_id"],
                "confirmed_correspondences": [], "correspondence_uncertainty": "symmetric corners or different visible faces; no forced identity",
                "uncertain_or_occluded": ["hidden faces and back edges excluded", "fine surface glints/texture excluded", "coarse thumbnail placement uncertainty 3 px"],
                "cameras": {}}
            for camera, (contour, ridges) in zip(("primary", "side"), pair):
                transform = next(value for value in transforms if value["sample"] == identifier and value["camera"] == camera)
                def native(points):
                    array = np.asarray(points, float)
                    return ((array - [transform["thumbnail_left"], transform["thumbnail_top"]]) / transform["scale"]
                            + transform["box_native"][:2]).tolist()
                straight_boundary = [] if curved else [[contour[i], contour[(i+1) % len(contour)]] for i in range(len(contour))]
                record["cameras"][camera] = {"visible_contour": native(contour), "true_internal_ridges": [native(line) for line in ridges],
                    "straight_boundary": [native(line) for line in straight_boundary], "curved_boundary": curved,
                    "placement_uncertainty_native_px": 3 / transform["scale"], "transform": transform}
                name = transform["sheet"]
                if name not in overlays:
                    overlays[name] = cv2.imread(str(output / "review" / name))
                canvas = overlays[name]
                offset = [0, transform["row"] * 290]
                cv2.polylines(canvas, [np.rint(np.asarray(contour) + offset).astype(np.int32)], True, (0,180,0), 1, cv2.LINE_AA)
                for line in ridges:
                    endpoints = np.rint(np.asarray(line) + offset).astype(int)
                    cv2.line(canvas, tuple(endpoints[0]), tuple(endpoints[1]), (255,0,255), 2, cv2.LINE_AA)
            records.append(record)
        for name, canvas in overlays.items():
            cv2.imwrite(str(output / "review" / name.replace(".jpg", "-manual.jpg")), canvas)
    # One unmistakable apex in a non-symmetric side-facing hexagonal pyramid
    # is visible in both views (calibration final row). Other symmetric face
    # vertices are deliberately left unconfirmed.
    record = records[23]
    def point(camera, uv):
        t = record["cameras"][camera]["transform"]
        return ((np.asarray(uv) - [t["thumbnail_left"], t["thumbnail_top"]])/t["scale"] + t["box_native"][:2]).tolist()
    record["confirmed_correspondences"] = [{"kind": "apex", "primary_uv": point("primary", [242,240]),
        "side_uv": point("side", [889,241]), "uncertainty": "coarse visible apex; no independent 3D truth"}]
    write_json(output / "review/manual-annotations.json", {"version": 1, "records": records,
        "creation_uses_predictions": False, "scope": "48 coarse independent development annotations; not certified human labels",
        "missing_strata": ["red curved", "cylinder", "black", "lightblue", "real touching instances"],
        "correspondence_evaluation_limit": "one confirmable asymmetric apex; all other corner identities uncertain"})


if __name__ == "__main__":
    main()
